/// <summary>
/// The class <c>GUPPricingAttributeRepository</c> is used as center place holding pricing attributes and pricing attribute providers.
/// </summary>
public static class GUPPricingAttributeRepository
{
    public static str CacheScope = classStr(GUPPricingAttributeRepository);
    public static str PricingAttrCacheKey = strFmt('cache-%1', classStr(GUPIPricingAttribute));
    public static str PricingAttrProviderCacheKey = strFmt('cache-%1', classStr(GUPIPricingAttributeProvider));

}

Method.Source:
private static Map getPricingAttributeProviders()
{
    List attrProviderList = SysExtensionAppClassFactory::getClassInstanceListFromSysAttribute(
            classStr(GUPIPricingAttributeProvider),
            new GUPPricingMetadataDiscoveryAttribute());
    ListEnumerator providerEnumerator = attrProviderList.getEnumerator();
    GUPIPricingAttributeProvider pricingAttrProvider;
    Map pricingAttributeProviders = new Map(Types::Integer, Types::Class);

    while(providerEnumerator.moveNext())
    {
        pricingAttrProvider = providerEnumerator.current();

        pricingAttributeProviders.add(classIdGet(pricingAttrProvider), pricingAttrProvider);
    }

    return pricingAttributeProviders;
}

private static Map getPricingAttributes()
{
    List attrList = SysExtensionAppClassFactory::getClassInstanceListFromSysAttribute(
            classStr(GUPIPricingAttribute),
            new GUPPricingMetadataDiscoveryAttribute());
    ListEnumerator attrEnumerator = attrList.getEnumerator();
    GUPIPricingAttribute pricingAttr;
    Map pricingAttributes = new Map(Types::Integer, Types::Class);

    while(attrEnumerator.moveNext())
    {
        pricingAttr = attrEnumerator.current();

        pricingAttributes.add(classIdGet(pricingAttr), pricingAttr);
    }

    return pricingAttributes;
}

public static List getAllPricingAttributes()
{
    List pricingAttrs = new List(Types::Class);

    MapEnumerator attrEnum = GUPPricingAttributeRepository::pricingAttributes().getEnumerator();
    while (attrEnum.moveNext())
    {
        pricingAttrs.addEnd(attrEnum.currentValue());
    }

    MapEnumerator providerEnum = GUPPricingAttributeRepository::pricingAttributeProviders().getEnumerator();
    GUPIPricingAttributeProvider provider;
    SetEnumerator providerAttrEnum;
    while (providerEnum.moveNext())
    {
        provider = providerEnum.currentValue();
        providerAttrEnum = provider.getPricingAttributes().getEnumerator();

        while (providerAttrEnum.moveNext())
        {
            pricingAttrs.addEnd(providerAttrEnum.current());
        }
    }

    return pricingAttrs;
}

/// <summary>
/// Get temporay price attribute records; these records are to be consumed as form control lookup datasource.
/// </summary>
/// <param name = "_sourceLevel">The source level of price attribute.</param>
/// <returns>Price attribute records.</returns>
public static GUPPricingAttributeTmp getPriceAttributeTmp(GUPPricingAttributeSourceLevel _sourceLevel)
{
    GUPPricingAttributeTmp priceAttrTmp;
    priceAttrTmp.clear();

    GUPPricingAttributeRepository::getPricingAttributes();

    List attributes = GUPPricingAttributeRepository::getAllPricingAttributes();
    Enumerator enum = attributes.getEnumerator();

    GUPIPricingAttribute pricingAttr;
    GUPPricingAttributeLink link;
    while (enum.moveNext())
    {
        pricingAttr = enum.current();
        link = GUPPricingAttributeRepository::toPriceAttributeLink(pricingAttr);
        priceAttrTmp.AttributeName = link.AttributeName;
        priceAttrTmp.PriceAttributeClassId = link.PriceAttributeClassId;
        priceAttrTmp.TypeName = link.TypeName;
        priceAttrTmp.ProviderClassId = link.AttributeProviderClassId;
        priceAttrTmp.insert();
    }

    return priceAttrTmp;
}

public static GUPIPricingAttribute priceAttribute(ClassId _attrClassId, ClassId _attrProviderClassId = 0, Name _attrName = '', str _attrTypeName = '')
{
    GUPIPricingAttribute pricingAttr;

    if (_attrClassId == classNum(GUPPricingAttributeEcoResAttribute))
    {
        if (!_attrProviderClassId || !_attrName)
        {
            throw error(strFmt(
                "@GlobalUnifiedPricing:GUPPricingAttributeRepository_MissigIdentification",
                classStr(GUPPricingAttributeProviderEcoResProductAttribute),
                classStr(GUPPricingAttributeEcoResAttribute)));
        }

        if (!GUPPricingAttributeRepository::pricingAttributeProviders().exists(_attrProviderClassId))
        {
            throw error(strFmt(
                "@GlobalUnifiedPricing:GUPPricingAttributeRepository_AttributeProviderDoesNotExist",
                _attrProviderClassId));
        }

        pricingAttr = new GUPPricingAttributeEcoResAttribute(
            _attrName,
            _attrTypeName,
            GUPPricingAttributeRepository::pricingAttributeProviders().lookup(_attrProviderClassId));
    }
    else
    {
            if (GUPPricingAttributeRepository::pricingAttributes().exists(_attrClassId))
            {
                pricingAttr = GUPPricingAttributeRepository::pricingAttributes().lookup(_attrClassId);
            }
            else
            {
                throw error(strFmt("@GlobalUnifiedPricing:GUPPricingAttributeRepository_AttributeDoesNotExist", _attrClassId, _attrName));
            }            
    }

    return pricingAttr;
}

internal static GUPPricingAttributeLink toPriceAttributeLink(GUPIPricingAttribute _pricingAttr)
{
    GUPPricingAttributeLink link;

    link.AttributeName = _pricingAttr.getName();
    link.PriceAttributeClassId = classIdGet(_pricingAttr);

    if (link.PriceAttributeClassId == classNum(GUPPricingAttributeEcoResAttribute))
    {
        link.AttributeProviderClassId = (_pricingAttr as GUPPricingAttributeEcoResAttribute).getEcoResAttributeProviderId();
        link.TypeName = (_pricingAttr as GUPPricingAttributeEcoResAttribute).getAttributeType();
    }

    return link;
}

internal static Object getPricingAttributeAttributeAsObject(
    GUPIPricingAttribute _pricingAttr,
    IdentifierName _attributeAsObjectName)
{
    // Only use this method on small batch of pricing attribute (e.g. a set of attribute fixed source level)
    ClassId attrClassId = classIdGet(_pricingAttr);
    DictClass dictClass;

    if (attrClassId == classNum(GUPPricingAttributeEcoResAttribute))
    {
        if (_attributeAsObjectName == attributeStr(GUPPricingAttributeFieldsDiscoveryAttribute))
        {
            return null;
        }

        attrClassId = (_pricingAttr as GUPPricingAttributeEcoResAttribute).getEcoResAttributeProviderId();
    }

    dictClass = new DictClass(attrClassId);
    Object attributeAsObject = dictClass.getAttribute(_attributeAsObjectName);

    if (!attributeAsObject)
    {
        throw error(strFmt("@GlobalUnifiedPricing:GUPPricingAttributeRepository_CheckAttributeAsObject", _attributeAsObjectName, classId2Name(attrClassId)));
    }

    return attributeAsObject;
}

private static Map pricingAttributes()
{
    SysGlobalCache cache = classFactory.globalCache();
    if (cache.isSet(
        GUPPricingAttributeRepository::CacheScope,
        GUPPricingAttributeRepository::PricingAttrCacheKey))
    {
        return cache.get(
            GUPPricingAttributeRepository::CacheScope,
            GUPPricingAttributeRepository::PricingAttrCacheKey);
    }
    else
    {
        Map pricingAttrs = GUPPricingAttributeRepository::getPricingAttributes();

        cache.set(
            GUPPricingAttributeRepository::CacheScope,
            GUPPricingAttributeRepository::PricingAttrCacheKey,
            pricingAttrs);

        return pricingAttrs;
    }
}

private static Map pricingAttributeProviders()
{
    SysGlobalCache cache = classFactory.globalCache();
    if (cache.isSet(
        GUPPricingAttributeRepository::CacheScope,
        GUPPricingAttributeRepository::PricingAttrProviderCacheKey))
    {
        return cache.get(
            GUPPricingAttributeRepository::CacheScope,
            GUPPricingAttributeRepository::PricingAttrProviderCacheKey);
    }
    else
    {
        Map pricingAttrProviders = GUPPricingAttributeRepository::getPricingAttributeProviders();

        cache.set(
            GUPPricingAttributeRepository::CacheScope,
            GUPPricingAttributeRepository::PricingAttrProviderCacheKey,
            pricingAttrProviders);

        return pricingAttrProviders;
    }
}
